export const INLINE_ASSETS = Object.freeze({"/index.html":{"contentType":"text/html; charset=utf-8","body":"<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#f8fafc\">\n  <meta name=\"color-scheme\" content=\"light\">\n  <meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n  <meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n  <meta name=\"apple-mobile-web-app-title\" content=\"Gmail Hub\">\n  <meta name=\"mobile-web-app-capable\" content=\"yes\">\n  <meta name=\"description\" content=\"Kelola banyak akun Gmail dari satu kotak masuk yang ringan, rapi, dan aman.\">\n  <meta name=\"referrer\" content=\"no-referrer\">\n  <link rel=\"manifest\" href=\"/manifest.webmanifest\">\n  <link rel=\"icon\" href=\"/icon.svg\" type=\"image/svg+xml\">\n  <link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n  <title>Unified Gmail Hub</title>\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <style>\n    :root {\n      color-scheme: light;\n      --canvas: #f8fafc;\n      --surface: #ffffff;\n      --surface-soft: #f1f5f9;\n      --line: #e2e8f0;\n      --ink: #0f172a;\n      --muted: #475569;\n      --faint: #64748b;\n      --blue: #2563eb;\n      --blue-soft: #eff6ff;\n      --red: #dc2626;\n      --green: #15803d;\n      --sidebar-width: 260px;\n      --list-width: 360px;\n      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n      font-synthesis: none;\n      text-rendering: optimizeLegibility;\n      -webkit-font-smoothing: antialiased;\n    }\n    * { box-sizing: border-box; }\n    html, body { width: 100%; min-height: 100%; margin: 0; background: var(--canvas); color: var(--ink); }\n    body { overflow: hidden; }\n    button, input, textarea, select { font: inherit; }\n    button { -webkit-tap-highlight-color: transparent; }\n    .app-shell { display: grid; grid-template-columns: var(--sidebar-width) var(--list-width) minmax(0, 1fr); height: 100dvh; min-height: 0; overflow: hidden; }\n    .sidebar { min-width: 0; background: #fff; border-right: 1px solid var(--line); display: flex; flex-direction: column; min-height: 0; }\n    .inbox-panel { min-width: 0; display: flex; flex-direction: column; background: #fff; border-right: 1px solid var(--line); min-height: 0; }\n    .reader-panel { min-width: 0; display: flex; flex-direction: column; background: var(--canvas); min-height: 0; }\n    .panel-scroll { overflow: auto; min-height: 0; overscroll-behavior: contain; scrollbar-width: thin; }\n    .brand-mark { width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center; background: #eff6ff; color: #1d4ed8; }\n    .nav-item { width: 100%; min-height: 44px; display: flex; align-items: center; gap: 11px; padding: 9px 12px; border-radius: 11px; color: var(--muted); text-align: left; transition: background .15s ease, color .15s ease; }\n    .nav-item:hover { background: #f8fafc; color: var(--ink); }\n    .nav-item.active { background: var(--blue-soft); color: #1d4ed8; font-weight: 650; }\n    .nav-item .nav-count { margin-left: auto; color: var(--faint); font-size: 12px; font-variant-numeric: tabular-nums; }\n    .account-row { display: flex; align-items: center; gap: 9px; width: 100%; min-height: 48px; padding: 7px 9px; border-radius: 11px; text-align: left; }\n    .account-row:hover, .account-row.active { background: #f1f5f9; }\n    .avatar { width: 34px; height: 34px; flex: 0 0 34px; display: grid; place-items: center; border-radius: 11px; background: #e2e8f0; color: #334155; font-size: 12px; font-weight: 750; }\n    .avatar.blue { background: #dbeafe; color: #1d4ed8; }\n    .avatar.green { background: #dcfce7; color: #166534; }\n    .avatar.violet { background: #ede9fe; color: #5b21b6; }\n    .avatar.amber { background: #fef3c7; color: #92400e; }\n    .account-meta { min-width: 0; flex: 1; }\n    .account-meta strong, .account-meta span { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n    .account-meta strong { font-size: 12px; font-weight: 650; color: var(--ink); }\n    .account-meta span { margin-top: 2px; font-size: 11px; color: var(--faint); }\n    .status-dot { width: 7px; height: 7px; border-radius: 50%; background: #16a34a; flex: 0 0 7px; }\n    .status-dot.error { background: var(--red); }\n    .toolbar-button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 42px; padding: 0 13px; border: 1px solid var(--line); border-radius: 10px; background: #fff; color: #334155; font-size: 13px; font-weight: 650; transition: background .15s ease, border-color .15s ease; }\n    .toolbar-button:hover { background: #f8fafc; border-color: #cbd5e1; }\n    .toolbar-button.primary { background: var(--blue); border-color: var(--blue); color: #fff; }\n    .toolbar-button.primary:hover { background: #1d4ed8; }\n    .toolbar-button:disabled { opacity: .55; cursor: not-allowed; }\n    .icon-button { width: 44px; height: 44px; border-radius: 10px; display: inline-grid; place-items: center; color: #475569; }\n    .icon-button:hover { background: #f1f5f9; color: var(--ink); }\n    .search-wrap { position: relative; }\n    .search-wrap input { width: 100%; height: 44px; border: 1px solid var(--line); border-radius: 11px; padding: 0 40px 0 40px; background: #fff; color: var(--ink); outline: none; font-size: 13px; }\n    .search-wrap input:focus { border-color: #93c5fd; box-shadow: 0 0 0 3px #dbeafe; }\n    .search-wrap .search-icon { position: absolute; left: 13px; top: 13px; color: #94a3b8; pointer-events: none; }\n    .search-wrap .clear-search { position: absolute; right: 5px; top: 3px; }\n    .range-select { width: min(100%, 220px); min-height: 38px; border: 1px solid var(--line); border-radius: 10px; padding: 0 34px 0 11px; background: #fff; color: #334155; font-size: 12px; font-weight: 650; outline: none; }\n    .range-select:focus { border-color: #93c5fd; box-shadow: 0 0 0 3px #dbeafe; }\n    .message-card { width: 100%; display: block; text-align: left; padding: 14px 15px; border-bottom: 1px solid #f1f5f9; border-left: 3px solid transparent; background: #fff; transition: background .12s ease; }\n    .message-card:hover { background: #f8fafc; }\n    .message-card.active { background: #eff6ff; border-left-color: var(--blue); }\n    .message-card.unread .sender, .message-card.unread .subject { font-weight: 750; color: var(--ink); }\n    .message-card .sender, .message-card .subject { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n    .message-card .sender { font-size: 13px; font-weight: 600; }\n    .message-card .subject { margin-top: 7px; font-size: 13px; font-weight: 550; color: #334155; }\n    .message-card .snippet { margin-top: 5px; font-size: 12px; line-height: 1.45; color: #64748b; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\n    .message-card .message-meta { margin-top: 9px; display: flex; align-items: center; gap: 7px; min-width: 0; color: #64748b; font-size: 10px; }\n    .message-card .message-meta .account-label { max-width: 130px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; border-radius: 5px; padding: 3px 6px; background: #f1f5f9; }\n    .unread-indicator { width: 7px; height: 7px; border-radius: 50%; background: var(--blue); flex: 0 0 7px; }\n    .reader-toolbar { min-height: 62px; display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 9px 20px; border-bottom: 1px solid var(--line); background: #fff; }\n    .reader-content { overflow: auto; min-height: 0; flex: 1; padding: 26px clamp(18px, 3vw, 42px) 32px; }\n    .reader-paper { max-width: 900px; margin: 0 auto; border: 1px solid var(--line); border-radius: 16px; background: #fff; overflow: hidden; }\n    .email-frame { display: block; width: 100%; min-height: 260px; border: 0; background: #fff; }\n    .reply-box { max-width: 900px; margin: 18px auto 0; border: 1px solid var(--line); border-radius: 15px; background: #fff; padding: 16px; }\n    .reply-box textarea { display: block; width: 100%; min-height: 112px; resize: vertical; border: 0; outline: 0; padding: 9px 0; color: var(--ink); font-size: 14px; line-height: 1.6; }\n    .reply-box textarea::placeholder { color: #94a3b8; }\n    .skeleton { position: relative; overflow: hidden; background: #e2e8f0; border-radius: 7px; }\n    .skeleton::after { content: \"\"; position: absolute; inset: 0; transform: translateX(-100%); background: linear-gradient(90deg, transparent, #f8fafc, transparent); animation: shimmer 1.4s infinite; }\n    @keyframes shimmer { 100% { transform: translateX(100%); } }\n    .spinner { width: 15px; height: 15px; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; display: inline-block; animation: spin .7s linear infinite; }\n    @keyframes spin { to { transform: rotate(360deg); } }\n    .toast-region { position: fixed; right: 18px; bottom: max(18px, env(safe-area-inset-bottom)); z-index: 100; display: grid; gap: 9px; width: min(370px, calc(100vw - 36px)); pointer-events: none; }\n    .toast { border: 1px solid var(--line); border-radius: 12px; background: #fff; box-shadow: 0 12px 35px rgba(15, 23, 42, .12); padding: 12px 14px; font-size: 13px; color: var(--ink); display: flex; align-items: flex-start; gap: 9px; animation: toast-in .18s ease-out; }\n    .toast.success .toast-mark { color: var(--green); }\n    .toast.error .toast-mark { color: var(--red); }\n    @keyframes toast-in { from { transform: translateY(8px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }\n    dialog { width: min(470px, calc(100vw - 28px)); max-height: min(90dvh, 680px); border: 1px solid var(--line); border-radius: 18px; padding: 0; background: #fff; color: var(--ink); box-shadow: 0 24px 80px rgba(15, 23, 42, .22); }\n    dialog::backdrop { background: rgba(15, 23, 42, .42); backdrop-filter: blur(2px); }\n    .modal-head { padding: 21px 22px 15px; border-bottom: 1px solid var(--line); }\n    .modal-body { padding: 19px 22px 22px; }\n    .form-label { display: block; margin-bottom: 7px; font-size: 12px; font-weight: 700; color: #334155; }\n    .form-control { width: 100%; min-height: 45px; border: 1px solid #cbd5e1; border-radius: 10px; padding: 0 12px; background: #fff; color: var(--ink); outline: none; font-size: 14px; }\n    .form-control:focus { border-color: #93c5fd; box-shadow: 0 0 0 3px #dbeafe; }\n    .field-hint { margin-top: 6px; font-size: 11px; line-height: 1.5; color: #64748b; }\n    .empty-state { display: grid; justify-items: center; text-align: center; padding: 50px 24px; }\n    .empty-icon { width: 54px; height: 54px; display: grid; place-items: center; border: 1px solid var(--line); border-radius: 17px; color: #64748b; background: #fff; }\n    .mobile-only { display: none; }\n    .mobile-list-head { display: none; }\n    .desktop-only { display: initial; }\n    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }\n    @media (max-width: 1180px) {\n      :root { --sidebar-width: 224px; --list-width: 330px; }\n      .reader-content { padding: 20px 18px 28px; }\n    }\n    @media (max-width: 920px) {\n      .app-shell { grid-template-columns: 220px minmax(0, 1fr); }\n      .reader-panel { display: none; }\n      body.message-open .sidebar, body.message-open .inbox-panel { display: none; }\n      body.message-open .reader-panel { display: flex; grid-column: 1 / -1; }\n      .mobile-only { display: inline-grid; }\n    }\n    @media (max-width: 640px) {\n      body { overflow: hidden; }\n      .app-shell { display: block; height: 100dvh; }\n      .sidebar { display: none; }\n      .inbox-panel { height: 100%; border: 0; }\n      .inbox-header { padding-top: max(13px, env(safe-area-inset-top)); }\n      .reader-panel { display: none; height: 100%; }\n      body.message-open .reader-panel { display: flex; }\n      body.message-open .inbox-panel { display: none; }\n      .reader-toolbar { padding: 7px 12px; min-height: 58px; }\n      .reader-content { padding: 13px 10px 22px; }\n      .reader-paper { border-radius: 12px; }\n      .reply-box { padding: 12px; margin-top: 12px; }\n      .message-card { padding: 14px 13px; }\n      .mobile-list-head { display: flex; }\n      .desktop-only { display: none !important; }\n    }\n    @media (prefers-reduced-motion: reduce) {\n      *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; transition-duration: .01ms !important; }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"app-shell\" id=\"appShell\">\n    <aside class=\"sidebar\" aria-label=\"Navigasi utama\">\n      <div class=\"px-5 pt-5 pb-4 flex items-center gap-3\">\n        <div class=\"brand-mark\" aria-hidden=\"true\">\n          <svg width=\"23\" height=\"23\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M3 7.5 12 14l9-6.5\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"3\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>\n        </div>\n        <div class=\"min-w-0\"><div class=\"text-sm font-bold tracking-tight\">Unified Gmail Hub</div><div class=\"text-[11px] text-slate-500 mt-0.5\">Satu pintu untuk semua inbox</div></div>\n      </div>\n      <div class=\"px-3 pb-3\">\n        <button class=\"toolbar-button primary w-full\" id=\"addAccountButton\" type=\"button\">\n          <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M12 5v14M5 12h14\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg>\n          Tambah Akun Gmail\n        </button>\n      </div>\n      <div class=\"px-3 pb-3\">\n        <button class=\"nav-item active\" id=\"allInboxButton\" type=\"button\" data-filter=\"all\">\n          <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M4 5h16v14H4z\" stroke=\"currentColor\" stroke-width=\"1.7\"/><path d=\"m4 7 8 6 8-6\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n          <span class=\"text-[13px]\">Semua Inbox</span><span class=\"nav-count\" id=\"allUnreadCount\">0</span>\n        </button>\n      </div>\n      <div class=\"px-3 pb-2\">\n        <div class=\"px-3 mb-2 flex items-center justify-between\"><span class=\"text-[10px] font-bold uppercase tracking-[.12em] text-slate-400\">Kategori</span></div>\n        <nav id=\"categoryNav\" class=\"space-y-1\" aria-label=\"Filter kategori\">\n          <div class=\"px-3 py-2 text-xs text-slate-400\">Belum ada kategori</div>\n        </nav>\n      </div>\n      <div class=\"mx-4 my-3 border-t border-slate-100\"></div>\n      <div class=\"px-3 flex items-center justify-between mb-2\">\n        <span class=\"px-3 text-[10px] font-bold uppercase tracking-[.12em] text-slate-400\">Akun terhubung</span>\n        <span id=\"accountTotal\" class=\"text-[11px] text-slate-400 tabular-nums\">0</span>\n      </div>\n      <div class=\"panel-scroll flex-1 px-3 pb-3\" id=\"accountNav\">\n        <div class=\"px-3 py-3 text-xs text-slate-400\">Memuat akun…</div>\n      </div>\n      <div class=\"p-4 border-t border-slate-100\">\n        <div class=\"flex items-center gap-2 text-[11px] text-slate-500\"><span class=\"status-dot\" id=\"connectionDot\"></span><span id=\"connectionLabel\">Menghubungkan…</span></div>\n        <div class=\"mt-2 text-[10px] text-slate-400 leading-relaxed\">Inbox menampilkan email 7 hari terakhir. Metadata lama tetap disimpan sementara di cache D1.</div>\n      </div>\n    </aside>\n\n    <main class=\"inbox-panel\" aria-label=\"Daftar email\">\n      <header class=\"inbox-header px-5 pt-5 pb-4 border-b border-slate-200 bg-white\">\n        <div class=\"mobile-list-head items-center justify-between mb-4\">\n          <div class=\"flex items-center gap-2\"><div class=\"brand-mark\" style=\"width:34px;height:34px\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M3 7.5 12 14l9-6.5\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"3\" stroke=\"currentColor\" stroke-width=\"2\"/></svg></div><span class=\"font-bold text-sm\">Gmail Hub</span></div>\n          <button class=\"toolbar-button primary\" id=\"mobileAddButton\" type=\"button\"><span aria-hidden=\"true\">＋</span> Tambah akun</button>\n        </div>\n        <div class=\"flex items-start justify-between gap-3 mb-4\">\n          <div class=\"min-w-0\"><p class=\"text-[11px] font-bold uppercase tracking-[.12em] text-blue-600\" id=\"listEyebrow\">KOTAK MASUK</p><h1 class=\"text-xl font-bold tracking-tight mt-1\" id=\"listTitle\">Semua Inbox</h1><p class=\"text-xs text-slate-500 mt-1\" id=\"listSubtitle\">Email dari 7 hari terakhir di seluruh akun terhubung</p></div>\n          <button class=\"toolbar-button primary shrink-0 desktop-only\" id=\"syncButton\" type=\"button\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M20 7v5h-5M4 17v-5h5\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M5.6 9a7 7 0 0 1 11.8-2L20 12M4 12l2.6 5a7 7 0 0 0 11.8-2\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>Sync Sekarang</button>\n        </div>\n        <div class=\"search-wrap\">\n          <svg class=\"search-icon\" width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\"><circle cx=\"10.8\" cy=\"10.8\" r=\"6.8\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"m16 16 4.2 4.2\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg>\n          <input id=\"searchInput\" type=\"search\" autocomplete=\"off\" placeholder=\"Cari pengirim, alamat, atau subjek…\" aria-label=\"Cari email dalam rentang terpilih\">\n          <button class=\"icon-button clear-search\" id=\"clearSearchButton\" type=\"button\" aria-label=\"Hapus pencarian\" hidden><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"m6 6 12 12M18 6 6 18\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg></button>\n        </div>\n        <div class=\"mt-3 flex items-center justify-between gap-3\">\n          <label for=\"inboxRange\" class=\"text-[11px] font-semibold text-slate-500\">Rentang email</label>\n          <select id=\"inboxRange\" class=\"range-select\" aria-label=\"Pilih rentang email\" title=\"Semua tersimpan menampilkan data yang tersedia di cache: retensi 90 hari, maksimal 1.000 email.\">\n            <option value=\"7d\" selected>7 hari terakhir</option>\n            <option value=\"30d\">30 hari terakhir</option>\n            <option value=\"90d\">90 hari terakhir</option>\n            <option value=\"all\">Semua tersimpan</option>\n          </select>\n        </div>\n        <p class=\"mt-1 text-[10px] leading-relaxed text-slate-400\">Email lama dari Gmail akan diisi bertahap melalui sinkronisasi awal. “Semua tersimpan” dibatasi cache 90 hari dan maksimal 1.000 metadata email.</p>\n        <div class=\"mobile-list-head items-center justify-between mt-3 gap-2\">\n          <span class=\"text-[11px] text-slate-500\" id=\"mobileCount\">Email dalam 7 hari terakhir</span>\n          <button class=\"toolbar-button\" id=\"mobileSyncButton\" type=\"button\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M20 7v5h-5M4 17v-5h5M5.6 9a7 7 0 0 1 11.8-2L20 12M4 12l2.6 5a7 7 0 0 0 11.8-2\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>Sync</button>\n        </div>\n      </header>\n      <div id=\"messageList\" class=\"panel-scroll flex-1\" aria-live=\"polite\">\n        <div class=\"p-4 space-y-4\" aria-label=\"Memuat email\"><div class=\"skeleton h-3 w-1/3\"></div><div class=\"skeleton h-3 w-2/3\"></div><div class=\"skeleton h-3 w-1/2\"></div><div class=\"border-t border-slate-100 pt-4 space-y-4\"><div class=\"skeleton h-16 w-full\"></div><div class=\"skeleton h-16 w-full\"></div><div class=\"skeleton h-16 w-full\"></div></div></div>\n      </div>\n      <div class=\"p-3 border-t border-slate-100 bg-white flex items-center justify-between text-[11px] text-slate-400\"><span id=\"listFooter\">Cache lokal D1</span><button id=\"loadMoreButton\" class=\"text-blue-600 font-semibold px-3 py-2 rounded-lg hover:bg-blue-50\" type=\"button\" hidden>Muat email sebelumnya · 7 hari</button></div>\n    </main>\n\n    <section class=\"reader-panel\" aria-label=\"Panel baca email\">\n      <div class=\"reader-toolbar\">\n        <div class=\"flex items-center gap-1\">\n          <button class=\"icon-button mobile-only\" id=\"backToListButton\" type=\"button\" aria-label=\"Kembali ke inbox\"><svg width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"m15 18-6-6 6-6\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></button>\n          <span class=\"text-xs font-semibold text-slate-500\" id=\"readerContext\">Pilih email untuk membaca</span>\n        </div>\n        <div class=\"flex items-center gap-1\">\n          <button class=\"icon-button\" id=\"openOriginalButton\" type=\"button\" aria-label=\"Buka di Gmail\" title=\"Buka di Gmail\" disabled><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M14 4h6v6M20 4l-9 9\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M18 13v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h5\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg></button>\n        </div>\n      </div>\n      <div class=\"reader-content\" id=\"readerContent\">\n        <div class=\"h-full min-h-[420px] grid place-items-center\">\n          <div class=\"text-center max-w-xs px-5\"><div class=\"empty-icon mx-auto\"><svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M4 5h16v14H4z\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"m4 7 8 6 8-6\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></div><h2 class=\"mt-4 text-sm font-bold\">Pilih email untuk dibaca</h2><p class=\"mt-2 text-xs leading-relaxed text-slate-500\">Pilih salah satu email di daftar. Isi email akan dimuat saat dibuka, bukan saat inbox pertama kali ditampilkan.</p></div>\n        </div>\n      </div>\n    </section>\n  </div>\n\n  <dialog id=\"addAccountDialog\">\n    <form id=\"addAccountForm\">\n      <div class=\"modal-head flex items-start justify-between gap-4\"><div><p class=\"text-[10px] font-bold tracking-[.12em] uppercase text-blue-600\">KONEKSI BARU</p><h2 class=\"text-lg font-bold mt-1\">Tambah Akun Gmail</h2><p class=\"text-xs text-slate-500 mt-1\">Hubungkan akun Google resmi dengan izin Gmail yang diminta.</p></div><button class=\"icon-button -mr-2 -mt-2\" type=\"button\" data-close=\"addAccountDialog\" aria-label=\"Tutup\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"m6 6 12 12M18 6 6 18\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg></button></div>\n      <div class=\"modal-body space-y-4\">\n        <div><label class=\"form-label\" for=\"newAlias\">Alias akun</label><input class=\"form-control\" id=\"newAlias\" name=\"alias\" maxlength=\"60\" placeholder=\"Contoh: Operasional\" required><p class=\"field-hint\">Nama singkat yang akan tampil di sidebar dan email.</p></div>\n        <div><label class=\"form-label\" for=\"newCategory\">Kategori</label><input class=\"form-control\" id=\"newCategory\" name=\"category\" maxlength=\"40\" list=\"categoryOptions\" placeholder=\"Contoh: Pekerjaan\" value=\"General\" required><datalist id=\"categoryOptions\"></datalist><p class=\"field-hint\">Gunakan kategori yang sama untuk mengelompokkan beberapa akun.</p></div>\n        <div class=\"rounded-xl border border-blue-100 bg-blue-50 p-3 text-xs leading-relaxed text-blue-900\"><strong>Privasi:</strong> aplikasi meminta akses Gmail untuk membaca inbox, menandai email telah dibaca, dan mengirim balasan. Refresh token disimpan terenkripsi di database aplikasi.</div>\n        <div class=\"flex justify-end gap-2 pt-1\"><button class=\"toolbar-button\" type=\"button\" data-close=\"addAccountDialog\">Batal</button><button class=\"toolbar-button primary\" type=\"submit\">Lanjut ke Google <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M7 17 17 7M8 7h9v9\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></button></div>\n      </div>\n    </form>\n  </dialog>\n\n  <dialog id=\"editAccountDialog\">\n    <form id=\"editAccountForm\">\n      <div class=\"modal-head flex items-start justify-between gap-4\"><div><p class=\"text-[10px] font-bold tracking-[.12em] uppercase text-blue-600\">PREFERENSI AKUN</p><h2 class=\"text-lg font-bold mt-1\">Edit Akun</h2><p class=\"text-xs text-slate-500 mt-1\" id=\"editAccountEmail\"></p></div><button class=\"icon-button -mr-2 -mt-2\" type=\"button\" data-close=\"editAccountDialog\" aria-label=\"Tutup\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"m6 6 12 12M18 6 6 18\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg></button></div>\n      <div class=\"modal-body space-y-4\">\n        <input type=\"hidden\" id=\"editAccountId\" name=\"id\">\n        <div><label class=\"form-label\" for=\"editAlias\">Alias akun</label><input class=\"form-control\" id=\"editAlias\" name=\"alias\" maxlength=\"60\" required></div>\n        <div><label class=\"form-label\" for=\"editCategory\">Kategori</label><input class=\"form-control\" id=\"editCategory\" name=\"category\" maxlength=\"40\" list=\"categoryOptions\" required></div>\n        <div class=\"flex items-center justify-between gap-3 pt-2\"><button class=\"text-sm font-semibold text-red-600 px-2 py-3 rounded-lg hover:bg-red-50\" id=\"deleteAccountButton\" type=\"button\">Hapus akun</button><div class=\"flex gap-2\"><button class=\"toolbar-button\" type=\"button\" data-close=\"editAccountDialog\">Batal</button><button class=\"toolbar-button primary\" type=\"submit\">Simpan</button></div></div>\n      </div>\n    </form>\n  </dialog>\n\n  <div id=\"toastRegion\" class=\"toast-region\" role=\"status\" aria-live=\"polite\"></div>\n\n  <script>\n    (() => {\n      \"use strict\";\n      const state = {\n        accounts: [], messages: [], selectedMessageId: null, selectedMessage: null,\n        category: \"\", accountId: \"\", query: \"\", range: \"7d\", offset: 0, nextOffset: null,\n        unreadTotal: 0, unreadByCategory: [], loadingInbox: false, loadingDetails: false,\n        syncing: false, editingAccount: null, requestSequence: 0,\n      };\n      const $ = (id) => document.getElementById(id);\n      const htmlEscape = (value) => String(value ?? \"\").replace(/[&<>\"']/g, (char) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[char]));\n      const initials = (value) => String(value || \"?\").trim().split(/[\\s@._-]+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join(\"\").toUpperCase() || \"?\";\n      const avatarTone = (id) => [\"blue\", \"green\", \"violet\", \"amber\"][Math.abs(Number(id) || 0) % 4];\n      const rangeLabel = (range = state.range) => ({\n        \"7d\": \"7 hari terakhir\",\n        \"30d\": \"30 hari terakhir\",\n        \"90d\": \"90 hari terakhir\",\n        all: \"semua email tersimpan\",\n      }[range] || \"7 hari terakhir\");\n      const dateLabel = (seconds) => {\n        const date = new Date(Number(seconds || 0) * 1000);\n        if (!Number.isFinite(date.getTime()) || !seconds) return \"Waktu tidak tersedia\";\n        const now = new Date();\n        const sameDay = date.toDateString() === now.toDateString();\n        return new Intl.DateTimeFormat(\"id-ID\", sameDay ? { hour: \"2-digit\", minute: \"2-digit\" } : { day: \"2-digit\", month: \"short\" }).format(date);\n      };\n      const fullDate = (seconds) => {\n        const date = new Date(Number(seconds || 0) * 1000);\n        return Number.isFinite(date.getTime()) && seconds ? new Intl.DateTimeFormat(\"id-ID\", { dateStyle: \"long\", timeStyle: \"short\" }).format(date) : \"Waktu tidak tersedia\";\n      };\n      const formatBytes = (bytes) => {\n        const size = Number(bytes || 0);\n        return size >= 1024 * 1024 ? `${(size / (1024 * 1024)).toFixed(1)} MB` : `${Math.max(1, Math.ceil(size / 1024))} KB`;\n      };\n\n      async function api(path, options = {}) {\n        const headers = new Headers(options.headers || {});\n        if (options.body !== undefined) headers.set(\"Content-Type\", \"application/json\");\n        headers.set(\"Accept\", \"application/json\");\n        const response = await fetch(path, { ...options, headers, credentials: \"same-origin\", cache: \"no-store\", redirect: \"follow\" });\n        const contentType = response.headers.get(\"content-type\") || \"\";\n        let data = {};\n        if (contentType.includes(\"application/json\")) {\n          try { data = await response.json(); } catch { data = {}; }\n        } else if (!response.ok) {\n          data = { error: `Server mengembalikan HTTP ${response.status}.` };\n        }\n        if (!response.ok) throw new Error(data.error || `Permintaan gagal (HTTP ${response.status}).`);\n        return data;\n      }\n\n      function toast(message, type = \"success\") {\n        const node = document.createElement(\"div\");\n        node.className = `toast ${type}`;\n        node.innerHTML = `<span class=\"toast-mark\" aria-hidden=\"true\">${type === \"error\" ? \"!\" : \"✓\"}</span><span class=\"min-w-0\">${htmlEscape(message)}</span>`;\n        $(\"toastRegion\").append(node);\n        window.setTimeout(() => node.remove(), 4200);\n      }\n\n      function setConnection(ok, label) {\n        $(\"connectionDot\").classList.toggle(\"error\", !ok);\n        $(\"connectionLabel\").textContent = label;\n      }\n\n      function setActiveNav() {\n        $(\"allInboxButton\").classList.toggle(\"active\", !state.category && !state.accountId);\n      }\n\n      function renderCategories() {\n        const map = new Map();\n        for (const item of state.unreadByCategory) map.set(String(item.category || \"General\"), Number(item.unread_count || 0));\n        const categories = [...new Set(state.accounts.map((account) => String(account.category || \"General\")))].sort((a, b) => a.localeCompare(b, \"id\"));\n        $(\"categoryNav\").innerHTML = categories.length ? categories.map((category) => {\n          const active = state.category === category && !state.accountId;\n          return `<button type=\"button\" class=\"nav-item ${active ? \"active\" : \"\"}\" data-category=\"${htmlEscape(category)}\"><svg width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M4 5h16v14H4z\" stroke=\"currentColor\" stroke-width=\"1.7\"/><path d=\"M8 9h8M8 13h5\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/></svg><span class=\"text-[13px] truncate\">${htmlEscape(category)}</span><span class=\"nav-count\">${map.get(category) || 0}</span></button>`;\n        }).join(\"\") : `<div class=\"px-3 py-2 text-xs text-slate-400\">Belum ada kategori</div>`;\n        $(\"categoryOptions\").innerHTML = categories.map((category) => `<option value=\"${htmlEscape(category)}\"></option>`).join(\"\");\n        setActiveNav();\n      }\n\n      function renderAccounts() {\n        $(\"accountTotal\").textContent = String(state.accounts.length);\n        if (!state.accounts.length) {\n          $(\"accountNav\").innerHTML = `<div class=\"px-3 py-3 text-xs leading-relaxed text-slate-400\">Belum ada akun. Tambahkan akun Gmail resmi untuk mulai menggabungkan inbox.</div>`;\n          return;\n        }\n        $(\"accountNav\").innerHTML = state.accounts.map((account) => {\n          const active = String(state.accountId) === String(account.id);\n          const syncError = String(account.sync_error || \"\"); const problem = Boolean(syncError); const needsReauth = /invalid_grant|hubungkan ulang akun|access token/i.test(syncError);\n          return `<div class=\"group flex items-center gap-1 rounded-xl ${active ? \"bg-slate-100\" : \"hover:bg-slate-50\"}\"><button type=\"button\" class=\"account-row flex-1 min-w-0 ${active ? \"active\" : \"\"}\" data-account=\"${Number(account.id)}\"><span class=\"avatar ${avatarTone(account.id)}\">${htmlEscape(initials(account.alias || account.email))}</span><span class=\"account-meta\"><strong>${htmlEscape(account.alias || account.email)}</strong><span>${htmlEscape(account.email)}</span></span>${needsReauth ? `<span class=\"text-[8px] font-bold text-red-600 whitespace-nowrap\">Perlu Re-auth</span>` : problem ? `<span class=\"text-[8px] font-bold text-amber-700 whitespace-nowrap\">Perlu dicek</span>` : Number(account.unread_count) > 0 ? `<span class=\"text-[11px] font-bold text-slate-500 tabular-nums\">${Number(account.unread_count)}</span>` : `<span class=\"status-dot\"></span>`}</button><button type=\"button\" class=\"icon-button shrink-0 opacity-60 hover:opacity-100\" style=\"width:34px;height:42px\" data-edit-account=\"${Number(account.id)}\" aria-label=\"Edit ${htmlEscape(account.alias || account.email)}\" title=\"Edit akun\"><svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"m14 5 5 5M4 20l4.2-.8L19 8.4a2.1 2.1 0 0 0-3-3L5.2 16.2 4 20Z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></button></div>`;\n        }).join(\"\");\n      }\n\n      function updateListHeading() {\n        const selectedAccount = state.accounts.find((account) => String(account.id) === String(state.accountId));\n        let title = \"Semua Inbox\";\n        const period = rangeLabel();\n        let subtitle = `Email ${period} dari seluruh akun terhubung`;\n        if (selectedAccount) { title = selectedAccount.alias || selectedAccount.email; subtitle = `Email ${period} · ${selectedAccount.email}`; }\n        else if (state.category) { title = state.category; subtitle = `Email ${period} · kategori ${state.category}`; }\n        if (state.query) subtitle = `Pencarian dalam ${period}: “${state.query}”`;\n        $(\"listTitle\").textContent = title;\n        $(\"listSubtitle\").textContent = subtitle;\n        $(\"listEyebrow\").textContent = selectedAccount ? \"AKUN GMAIL\" : state.category ? \"KATEGORI\" : \"KOTAK MASUK\";\n      }\n\n      function renderMessageCard(message) {\n        const unread = Number(message.is_unread) === 1;\n        const active = String(message.id) === String(state.selectedMessageId);\n        const sender = message.sender_name || message.sender_email || \"Pengirim tidak diketahui\";\n        const account = message.account_alias || message.account_email || \"Akun Gmail\";\n        const subject = message.subject || \"(Tanpa subjek)\";\n        return `<button type=\"button\" class=\"message-card ${unread ? \"unread\" : \"\"} ${active ? \"active\" : \"\"}\" data-message=\"${htmlEscape(message.id)}\"><div class=\"flex items-center gap-2\"><span class=\"${unread ? \"unread-indicator\" : \"w-[7px]\"}\" aria-hidden=\"true\"></span><span class=\"sender min-w-0 flex-1\">${htmlEscape(sender)}</span><time class=\"text-[10px] text-slate-400 shrink-0\">${htmlEscape(dateLabel(message.received_at))}</time></div><div class=\"subject pl-[15px]\">${htmlEscape(subject)}</div><div class=\"snippet pl-[15px]\">${htmlEscape(message.snippet || \"Tidak ada cuplikan email.\")}</div><div class=\"message-meta pl-[15px]\"><span class=\"account-label\">${htmlEscape(account)}</span><span>${htmlEscape(message.account_category || \"General\")}</span></div></button>`;\n      }\n\n      function renderMessages(append = false) {\n        const container = $(\"messageList\");\n        if (!state.messages.length) {\n          const period = rangeLabel();\n          const message = state.query ? `Tidak ada email dalam ${period} yang cocok dengan pencarian.` : state.accounts.length ? `Belum ada email dalam ${period}. Sinkronisasi awal akan mengisi riwayat secara bertahap; email tetap aman di Gmail asli.` : \"Hubungkan akun Gmail pertama untuk mulai menggunakan Unified Gmail Hub.\";\n          container.innerHTML = `<div class=\"empty-state\"><div class=\"empty-icon\"><svg width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M4 5h16v14H4z\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"m4 7 8 6 8-6\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></div><h2 class=\"mt-4 text-sm font-bold\">${state.query ? \"Email tidak ditemukan\" : state.accounts.length ? \"Belum ada email terbaru\" : \"Mulai dengan akun Gmail\"}</h2><p class=\"mt-2 max-w-xs text-xs leading-relaxed text-slate-500\">${htmlEscape(message)}</p>${!state.accounts.length ? `<button type=\"button\" class=\"toolbar-button primary mt-4\" id=\"emptyAddButton\">Tambah Akun Gmail</button>` : !state.query ? `<button type=\"button\" class=\"toolbar-button primary mt-4\" id=\"emptySyncButton\">Sync Sekarang</button>` : \"\"}</div>`;\n          $(\"loadMoreButton\").hidden = true;\n          return;\n        }\n        const html = state.messages.map(renderMessageCard).join(\"\");\n        if (append) container.insertAdjacentHTML(\"beforeend\", html); else container.innerHTML = html;\n        $(\"loadMoreButton\").hidden = state.nextOffset === null;\n        $(\"mobileCount\").textContent = `${state.messages.length} email · ${rangeLabel()}`;\n      }\n\n      function showInboxSkeleton() {\n        $(\"messageList\").innerHTML = `<div class=\"p-4 space-y-4\"><div class=\"skeleton h-3 w-1/3\"></div><div class=\"skeleton h-3 w-2/3\"></div><div class=\"skeleton h-3 w-1/2\"></div><div class=\"border-t border-slate-100 pt-4 space-y-4\"><div class=\"skeleton h-16 w-full\"></div><div class=\"skeleton h-16 w-full\"></div><div class=\"skeleton h-16 w-full\"></div><div class=\"skeleton h-16 w-full\"></div></div></div>`;\n      }\n\n      async function loadAccounts() {\n        const params = new URLSearchParams({ range: state.range });\n        const data = await api(`/api/accounts?${params.toString()}`);\n        state.accounts = Array.isArray(data.accounts) ? data.accounts : [];\n        renderAccounts();\n        return state.accounts;\n      }\n\n      async function loadInbox({ append = false } = {}) {\n        if (state.loadingInbox && append) return;\n        state.loadingInbox = true;\n        const sequence = ++state.requestSequence;\n        if (!append) { state.offset = 0; state.nextOffset = null; showInboxSkeleton(); }\n        const params = new URLSearchParams();\n        if (state.category) params.set(\"category\", state.category);\n        if (state.accountId) params.set(\"account_id\", state.accountId);\n        if (state.query) params.set(\"q\", state.query);\n        params.set(\"range\", state.range);\n        params.set(\"offset\", String(append ? state.offset : 0));\n        updateListHeading();\n        try {\n          const data = await api(`/api/inbox?${params.toString()}`);\n          if (sequence !== state.requestSequence) return;\n          const incoming = Array.isArray(data.messages) ? data.messages : [];\n          if (append) state.messages = [...state.messages, ...incoming]; else state.messages = incoming;\n          state.unreadTotal = Number(data.unread_total || 0);\n          state.unreadByCategory = Array.isArray(data.unread_by_category) ? data.unread_by_category : [];\n          state.nextOffset = data.next_offset === null || data.next_offset === undefined ? null : Number(data.next_offset);\n          if (append) state.offset = Number(params.get(\"offset\"));\n          renderMessages(append);\n          renderCategories();\n          $(\"allUnreadCount\").textContent = String(state.unreadTotal);\n          $(\"listFooter\").textContent = `${state.messages.length} email ditampilkan · ${rangeLabel()} · cache D1 (90 hari)`;\n          setConnection(true, \"Terhubung ke cache D1\");\n        } catch (error) {\n          if (sequence === state.requestSequence) {\n            $(\"messageList\").innerHTML = `<div class=\"empty-state\"><div class=\"empty-icon text-red-600\">!</div><h2 class=\"mt-4 text-sm font-bold\">Inbox tidak dapat dimuat</h2><p class=\"mt-2 max-w-xs text-xs leading-relaxed text-slate-500\">${htmlEscape(error.message)}</p><button class=\"toolbar-button mt-4\" id=\"retryInboxButton\" type=\"button\">Coba lagi</button></div>`;\n            setConnection(false, \"Koneksi bermasalah\");\n          }\n        } finally {\n          if (sequence === state.requestSequence) state.loadingInbox = false;\n        }\n      }\n\n      function updateSelectedMessageInList() {\n        const message = state.messages.find((item) => String(item.id) === String(state.selectedMessageId));\n        if (message) message.is_unread = 0;\n        const card = [...document.querySelectorAll(\"[data-message]\")].find((node) => node.dataset.message === String(state.selectedMessageId));\n        if (card) card.classList.remove(\"unread\");\n      }\n\n      function emailDocument(bodyHtml, bodyText) {\n        let content = bodyHtml;\n        if (!content) content = `<pre style=\"white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace;color:#0f172a\">${htmlEscape(bodyText || \"Email ini tidak memiliki konten teks yang dapat ditampilkan.\")}</pre>`;\n        return `<!doctype html><html lang=\"id\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; img-src data: cid:; style-src 'unsafe-inline'; font-src data:; media-src data:;\"><style>html,body{margin:0;padding:0;background:#fff;color:#0f172a;font:14px/1.65 Arial,sans-serif;overflow-wrap:anywhere}body{padding:22px 24px}img{max-width:100%;height:auto}table{max-width:100%;border-collapse:collapse}pre{white-space:pre-wrap;overflow-wrap:anywhere}blockquote{margin-left:0;padding-left:14px;border-left:3px solid #cbd5e1;color:#475569}a{color:#2563eb}*{max-width:100%}</style></head><body>${content || \"\"}</body></html>`;\n      }\n\n      function resizeEmailFrame(frame) {\n        try {\n          const doc = frame.contentDocument;\n          if (!doc) return;\n          const measure = () => {\n            const height = Math.max(doc.documentElement?.scrollHeight || 0, doc.body?.scrollHeight || 0, 260);\n            frame.style.height = `${Math.min(height + 4, 12000)}px`;\n          };\n          measure();\n          if (doc.fonts?.ready) doc.fonts.ready.then(measure).catch(() => {});\n          if (\"ResizeObserver\" in window && doc.body) {\n            const observer = new ResizeObserver(measure);\n            observer.observe(doc.body);\n            frame._resizeObserver = observer;\n          }\n          frame._measureTimer = window.setTimeout(measure, 500);\n        } catch (error) {\n          // Keep the iframe independently scrollable if the browser blocks measurement.\n          frame.style.height = \"70vh\";\n        }\n      }\n\n      function renderReader(message) {\n        const recipient = message.from?.name ? `${message.from.name} <${message.from.email || \"\"}>` : (message.from?.email || \"Pengirim tidak diketahui\");\n        const accountName = `${message.account_alias || \"Akun\"} <${message.account_email || \"\"}>`;\n        const attachmentHtml = Array.isArray(message.attachments) && message.attachments.length\n          ? `<div class=\"mt-5 pt-4 border-t border-slate-100\"><p class=\"text-[11px] font-bold text-slate-600 mb-2\">Lampiran · ${message.attachments.length}</p><div class=\"flex flex-wrap gap-2\">${message.attachments.map((attachment) => `<span class=\"inline-flex items-center gap-2 rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-[11px] text-slate-600\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M8 12.5 14.5 6a3 3 0 0 1 4.2 4.2l-8.1 8.1a5 5 0 0 1-7.1-7.1l8-8\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/></svg><span class=\"max-w-[220px] truncate\">${htmlEscape(attachment.name)}</span><span class=\"text-slate-400\">${htmlEscape(attachment.size_label || formatBytes(attachment.size_bytes))}</span></span>`).join(\"\")}</div><p class=\"mt-2 text-[10px] text-slate-400\">Lampiran hanya ditampilkan sebagai metadata; file tidak diunduh.</p></div>` : \"\";\n        $(\"readerContext\").textContent = `Dari ${recipient}`;\n        $(\"openOriginalButton\").disabled = false;\n        $(\"readerContent\").innerHTML = `<article class=\"reader-paper\"><header class=\"p-5 sm:p-7 border-b border-slate-100\"><div class=\"flex items-start gap-3\"><div class=\"avatar blue\">${htmlEscape(initials(message.from?.name || message.from?.email))}</div><div class=\"min-w-0 flex-1\"><div class=\"flex items-start justify-between gap-3\"><h1 class=\"text-lg sm:text-xl font-bold tracking-tight break-words\">${htmlEscape(message.subject || \"(Tanpa subjek)\")}</h1><span class=\"shrink-0 text-[10px] text-slate-400\">${htmlEscape(dateLabel(message.received_at))}</span></div><p class=\"text-xs text-slate-600 mt-2 break-words\">${htmlEscape(recipient)}</p><p class=\"text-[11px] text-slate-400 mt-1 break-words\">Diterima oleh ${htmlEscape(accountName)}</p><p class=\"text-[10px] text-slate-400 mt-1\">${htmlEscape(fullDate(message.received_at))}</p></div></div>${attachmentHtml}</header><div class=\"bg-white\"><iframe id=\"emailBodyFrame\" class=\"email-frame\" title=\"Isi email\" sandbox=\"allow-same-origin allow-popups allow-popups-to-escape-sandbox\" referrerpolicy=\"no-referrer\"></iframe></div></article><section class=\"reply-box\"><div class=\"flex flex-wrap items-center justify-between gap-2\"><div><p class=\"text-xs font-bold\">Balas email</p><p class=\"text-[10px] text-slate-500 mt-1\">Membalas sebagai: <strong class=\"text-slate-700\">${htmlEscape(accountName)}</strong></p></div><span class=\"text-[10px] text-slate-400\">Balasan mengikuti thread asli</span></div><textarea id=\"replyBody\" maxlength=\"100000\" placeholder=\"Tulis balasan…\" aria-label=\"Isi balasan email\"></textarea><div class=\"flex items-center justify-between gap-3 border-t border-slate-100 pt-3\"><span class=\"text-[10px] text-slate-400\">Email dikirim melalui akun penerima asli.</span><button class=\"toolbar-button primary\" id=\"sendReplyButton\" type=\"button\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"m21 3-7.5 18-3.5-7-7-3.5L21 3Z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M10 14 21 3\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/></svg>Kirim balasan</button></div></section>`;\n        const frame = $(\"emailBodyFrame\");\n        frame.onload = () => resizeEmailFrame(frame);\n        frame.srcdoc = emailDocument(message.body_html, message.body_text);\n      }\n\n      async function openMessage(messageId) {\n        state.selectedMessageId = String(messageId);\n        state.selectedMessage = null;\n        state.loadingDetails = true;\n        document.body.classList.add(\"message-open\");\n        renderMessages();\n        $(\"readerContext\").textContent = \"Memuat isi email…\";\n        $(\"openOriginalButton\").disabled = true;\n        $(\"readerContent\").innerHTML = `<div class=\"max-w-3xl mx-auto p-5 space-y-5\"><div class=\"skeleton h-7 w-2/3\"></div><div class=\"skeleton h-3 w-1/3\"></div><div class=\"skeleton h-3 w-1/2\"></div><div class=\"mt-8 space-y-3\"><div class=\"skeleton h-3 w-full\"></div><div class=\"skeleton h-3 w-11/12\"></div><div class=\"skeleton h-3 w-4/5\"></div><div class=\"skeleton h-40 w-full mt-6\"></div></div></div>`;\n        try {\n          const detailParams = new URLSearchParams({ range: state.range });\n          const message = await api(`/api/messages/${encodeURIComponent(messageId)}?${detailParams.toString()}`);\n          if (String(state.selectedMessageId) !== String(messageId)) return;\n          state.selectedMessage = message;\n          updateSelectedMessageInList();\n          renderReader(message);\n          void loadAccounts().then(() => loadInbox()).catch(() => {});\n        } catch (error) {\n          $(\"readerContent\").innerHTML = `<div class=\"empty-state\"><div class=\"empty-icon text-red-600\">!</div><h2 class=\"mt-4 text-sm font-bold\">Email tidak dapat dibuka</h2><p class=\"mt-2 max-w-xs text-xs leading-relaxed text-slate-500\">${htmlEscape(error.message)}</p><button class=\"toolbar-button mt-4\" id=\"retryMessageButton\" type=\"button\">Coba lagi</button></div>`;\n          toast(error.message, \"error\");\n        } finally { state.loadingDetails = false; }\n      }\n\n      async function sendReply() {\n        const body = $(\"replyBody\")?.value || \"\";\n        if (!body.trim()) { toast(\"Isi balasan belum ditulis.\", \"error\"); return; }\n        if (!state.selectedMessageId) return;\n        const button = $(\"sendReplyButton\");\n        button.disabled = true;\n        button.innerHTML = `<span class=\"spinner\"></span>Mengirim…`;\n        try {\n          const replyParams = new URLSearchParams({ range: state.range });\n          await api(`/api/messages/${encodeURIComponent(state.selectedMessageId)}/reply?${replyParams.toString()}`, { method: \"POST\", body: JSON.stringify({ body }) });\n          $(\"replyBody\").value = \"\";\n          toast(\"Balasan berhasil dikirim melalui akun yang menerima email asli.\");\n        } catch (error) { toast(error.message, \"error\"); }\n        finally {\n          if (button.isConnected) { button.disabled = false; button.innerHTML = `<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"m21 3-7.5 18-3.5-7-7-3.5L21 3Z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M10 14 21 3\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/></svg>Kirim balasan`; }\n        }\n      }\n\n      async function syncNow(button) {\n        if (state.syncing) return;\n        state.syncing = true;\n        const targets = [$(\"syncButton\"), $(\"mobileSyncButton\"), button].filter(Boolean);\n        for (const target of targets) { target.disabled = true; target.dataset.previousHtml = target.innerHTML; target.innerHTML = `<span class=\"spinner\"></span>Sync…`; }\n        try {\n          const result = await api(\"/api/sync\", { method: \"POST\", body: JSON.stringify({}) });\n          await loadAccounts();\n          await loadInbox();\n          toast(`Sinkronisasi selesai: ${Number(result.new_messages || 0)} email baru dari ${Array.isArray(result.synced_accounts) ? result.synced_accounts.length : 0} akun.`);\n        } catch (error) { toast(error.message, \"error\"); }\n        finally { state.syncing = false; for (const target of targets) { target.disabled = false; target.innerHTML = target.dataset.previousHtml || \"Sync Sekarang\"; } }\n      }\n\n      function openAddDialog() {\n        $(\"addAccountForm\").reset();\n        $(\"newCategory\").value = \"General\";\n        $(\"addAccountDialog\").showModal();\n        window.setTimeout(() => $(\"newAlias\").focus(), 50);\n      }\n\n      function openEditDialog(accountId) {\n        const account = state.accounts.find((item) => String(item.id) === String(accountId));\n        if (!account) return;\n        state.editingAccount = account;\n        $(\"editAccountId\").value = String(account.id);\n        $(\"editAccountEmail\").textContent = account.email;\n        $(\"editAlias\").value = account.alias || \"\";\n        $(\"editCategory\").value = account.category || \"General\";\n        $(\"editAccountDialog\").showModal();\n      }\n\n      async function saveAccount(event) {\n        event.preventDefault();\n        const id = Number($(\"editAccountId\").value);\n        const alias = $(\"editAlias\").value.trim();\n        const category = $(\"editCategory\").value.trim();\n        if (!alias || !category) { toast(\"Alias dan kategori wajib diisi.\", \"error\"); return; }\n        const button = $(\"editAccountForm\").querySelector('button[type=\"submit\"]');\n        button.disabled = true;\n        try {\n          await api(`/api/accounts/${id}`, { method: \"PATCH\", body: JSON.stringify({ alias, category }) });\n          $(\"editAccountDialog\").close();\n          await loadAccounts();\n          await loadInbox();\n          toast(\"Alias dan kategori akun berhasil diperbarui.\");\n        } catch (error) { toast(error.message, \"error\"); }\n        finally { button.disabled = false; }\n      }\n\n      async function deleteAccount() {\n        const account = state.editingAccount;\n        if (!account) return;\n        const confirmed = window.confirm(`Hapus akun ${account.email} dari Unified Gmail Hub? Seluruh metadata email yang tersimpan untuk akun ini juga akan dihapus.`);\n        if (!confirmed) return;\n        const button = $(\"deleteAccountButton\");\n        button.disabled = true;\n        try {\n          await api(`/api/accounts/${Number(account.id)}`, { method: \"DELETE\" });\n          if (String(state.accountId) === String(account.id)) { state.accountId = \"\"; state.selectedMessageId = null; state.selectedMessage = null; document.body.classList.remove(\"message-open\"); }\n          $(\"editAccountDialog\").close();\n          await loadAccounts();\n          await loadInbox();\n          toast(\"Akun dan cache metadata email berhasil dihapus.\");\n        } catch (error) { toast(error.message, \"error\"); }\n        finally { button.disabled = false; }\n      }\n\n      async function applyRange(range) {\n        if (![\"7d\", \"30d\", \"90d\", \"all\"].includes(range) || range === state.range) return;\n        state.range = range;\n        $(\"inboxRange\").value = range;\n        state.selectedMessageId = null;\n        state.selectedMessage = null;\n        document.body.classList.remove(\"message-open\");\n        try {\n          await loadAccounts();\n          await loadInbox();\n        } catch (error) {\n          toast(error.message, \"error\");\n        }\n      }\n\n      function applyCategory(category) {\n        state.category = category;\n        state.accountId = \"\";\n        state.selectedMessageId = null;\n        state.selectedMessage = null;\n        document.body.classList.remove(\"message-open\");\n        setActiveNav();\n        void loadInbox();\n      }\n\n      function applyAccount(accountId) {\n        state.accountId = String(accountId);\n        state.category = \"\";\n        state.selectedMessageId = null;\n        state.selectedMessage = null;\n        document.body.classList.remove(\"message-open\");\n        renderAccounts();\n        renderCategories();\n        void loadInbox();\n      }\n\n      function debounce(callback, delay) {\n        let timer;\n        return (...args) => { window.clearTimeout(timer); timer = window.setTimeout(() => callback(...args), delay); };\n      }\n\n      function bindEvents() {\n        $(\"addAccountButton\").addEventListener(\"click\", openAddDialog);\n        $(\"mobileAddButton\").addEventListener(\"click\", openAddDialog);\n        $(\"addAccountForm\").addEventListener(\"submit\", (event) => {\n          event.preventDefault();\n          const alias = $(\"newAlias\").value.trim();\n          const category = $(\"newCategory\").value.trim() || \"General\";\n          if (!alias || !category) { toast(\"Alias dan kategori wajib diisi.\", \"error\"); return; }\n          const target = new URL(\"/auth/add\", window.location.origin);\n          target.searchParams.set(\"alias\", alias);\n          target.searchParams.set(\"category\", category);\n          window.location.assign(target.toString());\n        });\n        $(\"editAccountForm\").addEventListener(\"submit\", saveAccount);\n        $(\"deleteAccountButton\").addEventListener(\"click\", deleteAccount);\n        $(\"allInboxButton\").addEventListener(\"click\", () => applyCategory(\"\"));\n        $(\"inboxRange\").addEventListener(\"change\", (event) => void applyRange(event.target.value));\n        $(\"categoryNav\").addEventListener(\"click\", (event) => {\n          const button = event.target.closest(\"[data-category]\");\n          if (button) applyCategory(button.dataset.category);\n        });\n        $(\"accountNav\").addEventListener(\"click\", (event) => {\n          const edit = event.target.closest(\"[data-edit-account]\");\n          if (edit) { openEditDialog(edit.dataset.editAccount); return; }\n          const button = event.target.closest(\"[data-account]\");\n          if (button) applyAccount(button.dataset.account);\n        });\n        $(\"messageList\").addEventListener(\"click\", (event) => {\n          const button = event.target.closest(\"[data-message]\");\n          if (button) void openMessage(button.dataset.message);\n          if (event.target.closest(\"#emptyAddButton\")) openAddDialog();\n          if (event.target.closest(\"#emptySyncButton\")) void syncNow($(\"syncButton\"));\n          if (event.target.closest(\"#retryInboxButton\")) void loadInbox();\n        });\n        $(\"readerContent\").addEventListener(\"click\", (event) => {\n          if (event.target.closest(\"#sendReplyButton\")) void sendReply();\n          if (event.target.closest(\"#retryMessageButton\")) void openMessage(state.selectedMessageId);\n        });\n        $(\"syncButton\").addEventListener(\"click\", () => void syncNow($(\"syncButton\")));\n        $(\"mobileSyncButton\").addEventListener(\"click\", () => void syncNow($(\"mobileSyncButton\")));\n        $(\"loadMoreButton\").addEventListener(\"click\", async () => {\n          if (state.nextOffset === null || state.loadingInbox) return;\n          const next = state.nextOffset;\n          state.offset = next;\n          await loadInbox({ append: true });\n        });\n        $(\"searchInput\").addEventListener(\"input\", debounce((event) => {\n          state.query = event.target.value.trim();\n          $(\"clearSearchButton\").hidden = !state.query;\n          state.selectedMessageId = null;\n          state.selectedMessage = null;\n          document.body.classList.remove(\"message-open\");\n          void loadInbox();\n        }, 300));\n        $(\"clearSearchButton\").addEventListener(\"click\", () => {\n          $(\"searchInput\").value = \"\";\n          state.query = \"\";\n          $(\"clearSearchButton\").hidden = true;\n          void loadInbox();\n          $(\"searchInput\").focus();\n        });\n        $(\"backToListButton\").addEventListener(\"click\", () => document.body.classList.remove(\"message-open\"));\n        $(\"openOriginalButton\").addEventListener(\"click\", () => {\n          const message = state.selectedMessage;\n          if (!message?.id || !message?.account_email) return;\n          const url = `https://mail.google.com/mail/u/0/?authuser=${encodeURIComponent(message.account_email)}#all/${encodeURIComponent(message.id)}`;\n          window.open(url, \"_blank\", \"noopener,noreferrer\");\n        });\n        document.querySelectorAll(\"[data-close]\").forEach((button) => button.addEventListener(\"click\", () => $(button.dataset.close).close()));\n        document.querySelectorAll(\"dialog\").forEach((dialog) => dialog.addEventListener(\"click\", (event) => {\n          if (event.target === dialog) dialog.close();\n        }));\n      }\n\n      async function boot() {\n        bindEvents();\n        try {\n          await loadAccounts();\n          await loadInbox();\n          if (state.accounts.some((account) => account.sync_error)) toast(\"Ada akun yang memerlukan autentikasi ulang. Periksa indikator Re-auth.\", \"error\");\n        } catch (error) {\n          setConnection(false, \"Tidak dapat terhubung\");\n          $(\"messageList\").innerHTML = `<div class=\"empty-state\"><div class=\"empty-icon text-red-600\">!</div><h2 class=\"mt-4 text-sm font-bold\">Aplikasi belum siap</h2><p class=\"mt-2 max-w-xs text-xs leading-relaxed text-slate-500\">${htmlEscape(error.message)} Pastikan Worker dan database D1 sudah dikonfigurasi.</p></div>`;\n        }\n        if (\"serviceWorker\" in navigator && window.isSecureContext) {\n          navigator.serviceWorker.register(\"/sw.js\", { scope: \"/\" }).catch(() => {});\n        }\n      }\n      document.addEventListener(\"DOMContentLoaded\", boot, { once: true });\n    })();\n  </script>\n</body>\n</html>\n"},"/manifest.webmanifest":{"contentType":"application/manifest+json","body":"{\n  \"id\": \"/\",\n  \"name\": \"Unified Gmail Hub\",\n  \"short_name\": \"Gmail Hub\",\n  \"description\": \"Kelola banyak akun Gmail dari satu kotak masuk.\",\n  \"lang\": \"id-ID\",\n  \"start_url\": \"/\",\n  \"scope\": \"/\",\n  \"display\": \"standalone\",\n  \"orientation\": \"any\",\n  \"background_color\": \"#f8fafc\",\n  \"theme_color\": \"#f8fafc\",\n  \"icons\": [\n    {\n      \"src\": \"/icon.svg\",\n      \"sizes\": \"any\",\n      \"type\": \"image/svg+xml\",\n      \"purpose\": \"any maskable\"\n    }\n  ]\n}\n"},"/sw.js":{"contentType":"text/javascript; charset=utf-8","body":"\"use strict\";\nconst CACHE_NAME = \"unified-gmail-hub-shell-v1\";\nconst APP_SHELL = [\"/\", \"/offline.html\", \"/manifest.webmanifest\", \"/icon.svg\"];\n\nself.addEventListener(\"install\", (event) => {\n  event.waitUntil(caches.open(CACHE_NAME).then((cache) => cache.addAll(APP_SHELL)).then(() => self.skipWaiting()));\n});\n\nself.addEventListener(\"activate\", (event) => {\n  event.waitUntil(\n    caches.keys().then((keys) => Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))))\n      .then(() => self.clients.claim()),\n  );\n});\n\nself.addEventListener(\"fetch\", (event) => {\n  const request = event.request;\n  const url = new URL(request.url);\n  if (request.method !== \"GET\" || url.origin !== self.location.origin || url.pathname.startsWith(\"/api/\") || url.pathname.startsWith(\"/auth/\")) return;\n\n  if (request.mode === \"navigate\") {\n    event.respondWith(fetch(request).catch(async () => (await caches.match(\"/\")) || caches.match(\"/offline.html\")));\n    return;\n  }\n\n  event.respondWith(fetch(request).then((response) => {\n    if (response.ok && response.type === \"basic\") {\n      const copy = response.clone();\n      caches.open(CACHE_NAME).then((cache) => cache.put(request, copy)).catch(() => {});\n    }\n    return response;\n  }).catch(async () => (await caches.match(request)) || Response.error()));\n});\n"},"/offline.html":{"contentType":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"id\">\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#f8fafc\"><title>Offline · Unified Gmail Hub</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f8fafc;color:#0f172a;font:16px system-ui,sans-serif;padding:24px;box-sizing:border-box}main{max-width:420px;background:#fff;border:1px solid #e2e8f0;border-radius:18px;padding:28px}h1{font-size:22px;margin:0 0 10px}p{color:#475569;line-height:1.6;font-size:14px}a{display:inline-flex;min-height:44px;align-items:center;padding:0 15px;border-radius:10px;background:#2563eb;color:white;text-decoration:none;font-weight:650;font-size:13px}</style></head>\n<body><main><h1>Koneksi sedang offline</h1><p>Unified Gmail Hub membutuhkan koneksi internet untuk memuat inbox dan berkomunikasi dengan Gmail. Setelah online kembali, buka ulang aplikasi ini.</p><a href=\"/\">Coba lagi</a></main></body>\n</html>\n"},"/icon.svg":{"contentType":"image/svg+xml","body":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\">\n  <rect width=\"512\" height=\"512\" rx=\"116\" fill=\"#eff6ff\"/>\n  <rect x=\"82\" y=\"132\" width=\"348\" height=\"248\" rx=\"44\" fill=\"#fff\" stroke=\"#2563eb\" stroke-width=\"28\"/>\n  <path d=\"m96 160 160 126 160-126\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"30\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n</svg>\n"}});
